def choose_move(observation):
    def clamp_dir(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def grid_size(obs):
        w = obs.get("grid_width")
        h = obs.get("grid_height")
        if not isinstance(w, int):
            w = 0
        if not isinstance(h, int):
            h = 0
        return w, h

    def step_toward(a, b):
        return [clamp_dir(b[0] - a[0]), clamp_dir(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_of(items, scorer, reverse=False):
        best_item = None
        best_score = None
        for item in items:
            try:
                score = scorer(item)
            except Exception:
                continue
            if best_item is None or (score > best_score if reverse else score < best_score):
                best_item = item
                best_score = score
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    w, h = grid_size(observation)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = []
        if w > 0 and h > 0:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(0, 0), (-10, -10), (10, -10), (-10, 10), (10, 10)]
        target = best_of(corners, lambda c: manhattan(c, opp_pos), reverse=True)
        if target is None:
            return [0, 0]
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            best = best_of(targets, lambda item: manhattan(pos(item, self_pos), self_pos))
            if best is not None:
                return step_toward(self_pos, pos(best, self_pos))
        enemy_base = observation.get("opponent_base") or observation.get("opponent_spawn") or observation.get("opponent_position")
        if isinstance(enemy_base, (list, tuple)) and len(enemy_base) >= 2:
            return step_toward(self_pos, pos(enemy_base, self_pos))
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        need = observation.get("resource_goal")
        if isinstance(need, (list, tuple)) and len(need) >= 2:
            target = best_of(resources, lambda item: manhattan(pos(item, self_pos), self_pos) + manhattan(pos(item, self_pos), pos(need, self_pos)))
        else:
            target = best_of(resources, lambda item: manhattan(pos(item, self_pos), self_pos))
        if target is not None:
            return step_toward(self_pos, pos(target, self_pos))

    if ox != sx or oy != sy:
        return step_toward(self_pos, opp_pos)

    return [0, 0]

